import datetime
from types import SimpleNamespace

from lumibot.components.options_helper import OptionsHelper
from lumibot.entities import Asset


class _DummyThetaDataBacktestingPandas:
    """Named to match the real ThetaData backtesting data source class."""

    __name__ = "ThetaDataBacktestingPandas"


class _DummyBroker:
    def __init__(self):
        # Instance whose class name matches what OptionsHelper gates on.
        class ThetaDataBacktestingPandas:  # noqa: N801 - intentional for __name__ match
            pass

        self.data_source = ThetaDataBacktestingPandas()


class _StubChains:
    def __init__(self, strikes):
        self._strikes = strikes

    def strikes(self, expiry, right):
        return list(self._strikes)


class _StubStrategy:
    def __init__(self, strikes, *, max_spread_pct=None):
        self.is_backtesting = True
        self.broker = _DummyBroker()
        self.parameters = {}
        if max_spread_pct is not None:
            self.parameters["max_spread_pct"] = max_spread_pct
        self._chains = _StubChains(strikes)
        self._now = datetime.datetime(2026, 1, 2, 10, 30)

    def log_message(self, *args, **kwargs):
        return None

    def get_chains(self, underlying_asset):
        return self._chains

    def get_datetime(self):
        return self._now

    def get_quote(self, option_asset):
        if option_asset.strike == 39.0:
            return SimpleNamespace(bid=0.0, ask=0.5)
        if option_asset.strike == 38.0:
            return SimpleNamespace(bid=0.05, ask=0.25)
        if option_asset.strike == 37.0:
            return SimpleNamespace(bid=0.15, ask=0.25)
        return None

    def get_last_price(self, option_asset):
        return None


def test_find_next_valid_option_prefers_actionable_two_sided_quotes_in_thetadata_backtests():
    strategy = _StubStrategy(strikes=[38.0, 39.0])
    helper = OptionsHelper(strategy)

    underlying = Asset("MFC", asset_type=Asset.AssetType.STOCK)
    expiry = datetime.date(2026, 3, 20)

    option = helper.find_next_valid_option(
        underlying_asset=underlying,
        rounded_underlying_price=39.0,
        expiry=expiry,
        put_or_call="call",
    )

    assert option is not None
    assert option.strike == 38.0


def test_find_next_valid_option_respects_strategy_max_spread_pct_when_present():
    strategy = _StubStrategy(strikes=[37.0, 38.0, 39.0], max_spread_pct=0.6)
    helper = OptionsHelper(strategy)

    underlying = Asset("MFC", asset_type=Asset.AssetType.STOCK)
    expiry = datetime.date(2026, 3, 20)

    option = helper.find_next_valid_option(
        underlying_asset=underlying,
        rounded_underlying_price=39.0,
        expiry=expiry,
        put_or_call="call",
    )

    assert option is not None
    assert option.strike == 37.0


def test_find_next_valid_option_backs_off_longer_when_no_quote_history_exists():
    strategy = _StubStrategy(strikes=[38.0, 39.0])
    helper = OptionsHelper(strategy)

    # Force all quote probes to return "no data".
    def _no_quote(*args, **kwargs):
        return None

    strategy.get_quote = _no_quote  # type: ignore[method-assign]

    underlying = Asset("MFC", asset_type=Asset.AssetType.STOCK)
    expiry = datetime.date(2026, 3, 20)

    option = helper.find_next_valid_option(
        underlying_asset=underlying,
        rounded_underlying_price=39.0,
        expiry=expiry,
        put_or_call="call",
    )

    assert option is None
    cooldown = getattr(helper, "_valid_option_search_cooldown", {})
    assert cooldown[(underlying.symbol, expiry, "CALL")] == strategy.get_datetime() + datetime.timedelta(days=30)

import pandas as pd

from lumibot.tools.yahoo_helper import YahooHelper


def test_get_symbol_actions_uses_symbol_data(monkeypatch):
    idx = pd.DatetimeIndex(["2024-01-01", "2024-01-02"])
    sample = pd.DataFrame(
        {
            "Dividends": [0.0, 0.5],
            "Stock Splits": [0.0, 0.0],
        },
        index=idx,
    )

    monkeypatch.setattr(YahooHelper, "get_symbol_data", staticmethod(lambda symbol, caching=True: sample))
    actions = YahooHelper.get_symbol_actions("AAPL", caching=True)

    assert list(actions.columns) == ["Dividends", "Stock Splits"]
    assert len(actions) == 1
    assert actions.iloc[0]["Dividends"] == 0.5
    assert actions.iloc[0]["Stock Splits"] == 0.0


def test_get_symbols_actions_uses_symbols_data(monkeypatch):
    idx = pd.DatetimeIndex(["2024-01-01", "2024-01-02"])
    payload = {
        "AAPL": pd.DataFrame(
            {
                "Dividends": [0.0, 0.25],
                "Stock Splits": [0.0, 0.0],
            },
            index=idx,
        ),
        "MSFT": pd.DataFrame(
            {
                "Dividends": [0.0, 0.0],
                "Stock Splits": [0.0, 2.0],
            },
            index=idx,
        ),
    }

    monkeypatch.setattr(YahooHelper, "get_symbols_data", staticmethod(lambda symbols, caching=True: payload))
    actions = YahooHelper.get_symbols_actions(["AAPL", "MSFT"], caching=True)

    assert set(actions.keys()) == {"AAPL", "MSFT"}
    assert len(actions["AAPL"]) == 1
    assert len(actions["MSFT"]) == 1
    assert actions["AAPL"].iloc[0]["Dividends"] == 0.25
    assert actions["MSFT"].iloc[0]["Stock Splits"] == 2.0

from lumibot.components.agents.runtime import _classify_agent_error


class _ProviderError(Exception):
    def __init__(self, message: str, status_code: int | None = None):
        super().__init__(message)
        if status_code is not None:
            self.status_code = status_code


def test_xai_monthly_spending_limit_classifies_as_billing():
    exc = _ProviderError(
        '{"code":"Some resource has been exhausted","error":"Your team has either used all available credits or reached its monthly spending limit."}',
        status_code=429,
    )

    assert _classify_agent_error(exc) == "billing"


def test_plain_rate_limit_still_classifies_as_transient():
    exc = type("RateLimitError", (Exception,), {})("too many requests right now")

    assert _classify_agent_error(exc) == "transient"
